package com.hp.thermalshockreforged.entity;
import net.minecraft.world.entity.EntitySpawnReason;
import java.util.*;
import com.mojang.authlib.GameProfile;
import com.hp.thermalshockreforged.entity.huntress.*;
import com.hp.thermalshockreforged.entity.maiden.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.Pose;
import net.minecraft.world.entity.animal.cow.Cow;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.minecraft.gametest.framework.GameTestHelper;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.event.entity.EntityJoinLevelEvent;
import net.neoforged.neoforge.common.NeoForge;
public final class DimensionPlayerIdentityTests {
    private static final Map<UUID,List<Shot>> SHOTS=new java.util.concurrent.ConcurrentHashMap<>();
    static{NeoForge.EVENT_BUS.addListener(DimensionPlayerIdentityTests::joined);}
    public static void actualMaidenDimensionChangeCancelsOldLevelVolley(GameTestHelper h){var nether=h.getLevel().getServer().getLevel(Level.NETHER);h.assertTrue(nether!=null,"The server must expose its actual Nether ServerLevel");boolean addedForce=nether.setChunkForced(0,0,true);nether.getChunkSource().addTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(0,0),2);awaitMaidenNether(h,nether,addedForce,400);}
    private static void awaitMaidenNether(GameTestHelper h,net.minecraft.server.level.ServerLevel nether,boolean addedForce,int remaining){var destination=new BlockPos(0,80,0);if(!nether.isPositionEntityTicking(destination)){if(remaining>0){h.runAfterDelay(1,()->awaitMaidenNether(h,nether,addedForce,remaining-1));return;}releaseNether(nether,addedForce);h.fail("Native Nether destination did not become entity-ticking within the fixture deadline: time="+nether.getGameTime()+", chunk="+nether.getChunkSource().hasChunk(0,0)+", entitiesLoaded="+nether.areEntitiesLoaded(0L)+", entityTicking="+nether.isPositionEntityTicking(destination));return;}var owner=maiden(h,8,2,8);owner.getRandom().setSeed(seed(true));var target=cow(h,11,2,8);owner.beginAttack(target);var old=volleys(h,owner);if(old.size()!=1){releaseNether(nether,addedForce);h.assertTrue(false,"Maiden must have one committed old-level volley");return;}var task=old.getFirst();UUID ownerId=owner.getUUID();Entity moved=owner.teleport(new net.minecraft.world.level.portal.TeleportTransition(nether,new Vec3(.5,80,.5),Vec3.ZERO,owner.getYRot(),owner.getXRot(),net.minecraft.world.level.portal.TeleportTransition.DO_NOTHING));boolean visible=moved!=null&&nether.getEntity(ownerId)==moved;h.assertTrue(moved instanceof MaidenEntity&&moved.level()==nether&&moved.getUUID().equals(ownerId)&&owner.isRemoved()&&visible,"Native dimension change must place the same Maiden UUID in an entity-ticking Nether chunk; moved="+(moved==null?"null":moved.getUUID()+"/"+moved.getId()+"/removed="+moved.isRemoved()+"/added="+moved.isAddedToLevel())+", lookup="+visible+", ticking="+nether.isPositionEntityTicking(destination)+", sourceRemoved="+owner.isRemoved());Vec3 oldPosition=owner.position();h.runAfterDelay(1,()->{try{var bullets=h.getLevel().getEntitiesOfClass(com.hp.thermalshockreforged.entity.projectile.BloodBulletEntity.class,new AABB(BlockPos.containing(oldPosition)).inflate(64));var levels=java.util.stream.StreamSupport.stream(h.getLevel().getServer().getAllLevels().spliterator(),false).map(level->level.dimension()+"="+level.getEntity(ownerId)).toList();h.assertTrue(task.isRemoved()&&bullets.isEmpty(),"Observed cross-level caster must cancel only its stale old-level volley after a real END tick; task="+task.getUUID()+"/removed="+task.isRemoved()+"/armed="+snapshot(task).getBooleanOr("MaidenArmed",false)+", moved="+(moved==null?"null":moved.getUUID()+"/"+moved.getId()+"/"+moved.level().dimension()+"/removed="+moved.isRemoved()+"/added="+moved.isAddedToLevel())+", lookup="+(moved!=null&&nether.getEntity(ownerId)==moved)+", bullets="+bullets.size()+", serverLevels="+levels);h.succeed();}finally{if(moved!=null)moved.discard();releaseNether(nether,addedForce);}});}
    private static void releaseNether(net.minecraft.server.level.ServerLevel nether,boolean addedForce){nether.getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(0,0),2);if(addedForce)nether.setChunkForced(0,0,false);}
    public static void huntressRejectsDimensionChangeByItsNativePolicy(GameTestHelper h){var owner=HuntressContent.BOSS.get().create(h.getLevel(), net.minecraft.world.entity.EntitySpawnReason.COMMAND);owner.setNoAi(true);owner.setPos(pos(h,8,2,8));h.getLevel().addFreshEntity(owner);var nether=h.getLevel().getServer().getLevel(Level.NETHER);h.assertTrue(nether!=null&&!owner.canTeleport(h.getLevel(),nether)&&owner.level()==h.getLevel(),"Huntress native policy must reject cross-dimension transfer before a transition can be requested");h.succeed();}
    public static void volleyNbtDoesNotRebindToNewPlayerObjectWithSameUuid(GameTestHelper h){var owner=maiden(h,8,2,8);owner.getRandom().setSeed(seed(true));UUID playerId=UUID.randomUUID();var old=player(h,playerId,"old-target");old.setPose(Pose.SWIMMING);old.snapTo(pos(h,11,2,8).x,pos(h,11,2,8).y,pos(h,11,2,8).z,0,0);float oldEye=old.getEyeHeight();owner.beginAttack(old);var tasks=volleys(h,owner);h.assertTrue(tasks.size()==1,"Volley must snapshot the original player target");var task=tasks.getFirst();for(int i=0;i<28;i++)task.endTick(h.getLevel());CompoundTag data=snapshot(task);task.discard();com.hp.thermalshockreforged.gametest.PlayerInteractionTests.release(h,old);data.put("UUID",net.minecraft.core.UUIDUtil.CODEC.encodeStart(net.minecraft.nbt.NbtOps.INSTANCE,UUID.randomUUID()).result().orElseThrow());var replacement=player(h,playerId,"replacement");replacement.setPose(Pose.STANDING);replacement.snapTo(pos(h,16,2,8).x,pos(h,16,2,8).y,pos(h,16,2,8).z,0,0);replacement.snapTo(pos(h,16,2,8).x,pos(h,16,2,8).y,pos(h,16,2,8).z,0,0);h.assertTrue(replacement.getId()!=data.getIntOr("MaidenTargetEntityId", -1)&&Math.abs(replacement.getEyeHeight()-oldEye)>.2,"Fixture must replace the player instance while retaining only its UUID and change eye height");var restored=MaidenContent.VOLLEY.get().create(h.getLevel(), net.minecraft.world.entity.EntitySpawnReason.COMMAND);restore(h, restored, data);h.getLevel().addFreshEntity(restored);restored.endTick(h.getLevel());var shots=List.copyOf(SHOTS.getOrDefault(owner.getUUID(),List.of()));h.assertTrue(restored.isRemoved()&&shots.size()==8&&shots.stream().allMatch(s->s.owner().equals(owner.getUUID())&&Math.abs(s.y()-(owner.getY()+oldEye))<.001),"Restored wave must use captured old-instance eye height and must not rebind to the replacement player");com.hp.thermalshockreforged.gametest.PlayerInteractionTests.release(h,replacement);h.succeed();}
    private static long seed(boolean single){double c=MaidenConfig.SINGLE_CHANCE.get();for(long i=0;i<100000;i++)if((net.minecraft.util.RandomSource.create(i).nextDouble()<c)==single)return i;throw new IllegalStateException();}
    private static MaidenEntity maiden(GameTestHelper h,int x,int y,int z){var e=MaidenContent.MAIDEN.get().create(h.getLevel(), net.minecraft.world.entity.EntitySpawnReason.COMMAND);e.setNoAi(true);e.setPos(pos(h,x,y,z));h.getLevel().addFreshEntity(e);return e;}
    private static Cow cow(GameTestHelper h,int x,int y,int z){var e=EntityType.COW.create(h.getLevel(), net.minecraft.world.entity.EntitySpawnReason.COMMAND);e.setNoAi(true);e.setNoGravity(true);e.setPos(pos(h,x,y,z));h.getLevel().addFreshEntity(e);return e;}
    private static net.minecraft.server.level.ServerPlayer player(GameTestHelper h,UUID id,String name){var p=new net.minecraft.server.level.ServerPlayer(h.getLevel().getServer(),h.getLevel(),new GameProfile(id,name),net.minecraft.server.level.ClientInformation.createDefault());return com.hp.thermalshockreforged.gametest.PlayerInteractionTests.connect(h,p,net.minecraft.world.level.GameType.SURVIVAL,8,2,8);}
    private static Vec3 pos(GameTestHelper h,int x,int y,int z){return Vec3.atCenterOf(h.absolutePos(new BlockPos(x,y,z)));}
    private static List<MaidenVolleyEntity> volleys(GameTestHelper h,MaidenEntity owner){return h.getLevel().getEntitiesOfClass(MaidenVolleyEntity.class,new AABB(owner.blockPosition()).inflate(64),t->{var n=snapshot(t);return uuid(n, "MaidenCaster") != null&&uuid(n, "MaidenCaster").equals(owner.getUUID());});}
    private static void joined(EntityJoinLevelEvent event){if(event.getEntity() instanceof com.hp.thermalshockreforged.entity.projectile.BloodBulletEntity bullet&&event.getLevel() instanceof net.minecraft.server.level.ServerLevel level){var n=snapshot(bullet);if(uuid(n, "Owner") != null){UUID id=uuid(n, "Owner");SHOTS.computeIfAbsent(id,k->new java.util.concurrent.CopyOnWriteArrayList<>()).add(new Shot(id,bullet.getY()));}}}
    private record Shot(UUID owner,double y){}


    private static CompoundTag snapshot(Entity entity) { var output=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,entity.registryAccess()); entity.saveWithoutId(output); return output.buildResult(); }
    private static void restore(GameTestHelper helper, Entity entity, CompoundTag tag) { entity.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,helper.getLevel().registryAccess(),tag)); }
    private static java.util.UUID uuid(CompoundTag tag, String key) { net.minecraft.nbt.Tag value=tag.get(key); return value==null?null:net.minecraft.core.UUIDUtil.LENIENT_CODEC.parse(net.minecraft.nbt.NbtOps.INSTANCE,value).result().orElse(null); }
    public static void register() {
        com.hp.thermalshockreforged.gametest.TsrGameTests.addDedicated("history_dimension_player_identity_tests_actual_maiden_dimension_change_cancels_old_level_volley", DimensionPlayerIdentityTests::actualMaidenDimensionChangeCancelsOldLevelVolley, 100, "supernova_server");
        com.hp.thermalshockreforged.gametest.TsrGameTests.add("history_dimension_player_identity_tests_huntress_rejects_dimension_change_by_its_native_policy", DimensionPlayerIdentityTests::huntressRejectsDimensionChangeByItsNativePolicy, 100, "supernova_server");
        com.hp.thermalshockreforged.gametest.TsrGameTests.add("history_dimension_player_identity_tests_volley_nbt_does_not_rebind_to_new_player_object_with_same_uuid", DimensionPlayerIdentityTests::volleyNbtDoesNotRebindToNewPlayerObjectWithSameUuid, 100, "supernova_server");
    }
}


